255	// expectedImpacts is the oracle-derived complete answer for Impacts(origin),
256	// sorted exactly as the production contract requires.
257	func expectedImpacts(names []string, oracle *lineageTestOracle, origin string) []Impact {
258		want := []Impact{}
259		for _, to := range names {
260			if to == origin {
261				continue
262			}
263			if distance, path, ok := oracle.shortest(origin, to); ok {
264				want = append(want, Impact{Dataset: to, Distance: distance, Path: path})
265			}
266		}
267		sort.Slice(want, func(i, j int) bool {
268			if want[i].Distance != want[j].Distance {
269				return want[i].Distance < want[j].Distance
270			}
271			return want[i].Dataset < want[j].Dataset
272		})
273		return want
274	}
275	
276	// expectedUpstreams is the oracle-derived complete answer for Upstreams(target):
277	// every source with its path written from source to target.
278	func expectedUpstreams(names []string, oracle *lineageTestOracle, target string) []Upstream {
279		want := []Upstream{}
280		for _, from := range names {
281			if from == target {
282				continue
283			}
284			if distance, path, ok := oracle.shortest(from, target); ok {
285				want = append(want, Upstream{Dataset: from, Distance: distance, Path: path})
286			}
287		}
288		sort.Slice(want, func(i, j int) bool {
289			if want[i].Distance != want[j].Distance {
290				return want[i].Distance < want[j].Distance
291			}
292			return want[i].Dataset < want[j].Dataset
293		})
294		return want
295	}
296	
297	// layeredCorrespondenceRegistrations builds a graph spanning direct and
298	// multi-level (up to five edges) relationships, diamonds, merges where the
299	// branches arrive at different depths, a merge whose equal-length routes are
300	// decided by the full path rather than the merge node's direct-upstream order,
301	// two disconnected components and fully isolated datasets:
302	//
303	//	root -> a -> z ------> m ----\
304	//	  \      \-> long ---/  \     \
305	//	   \      \-> q -> merge2 -> tip -> leaf
306	//	    \-> b -> c ------/^  (merge2 also takes q at one level less)
307	//	tip also takes long at the same depth as merge2.
308	//	r2 -> d1 -> d2 is a separate component; iso and solo are isolated.
309	func layeredCorrespondenceRegistrations() [][]string {
310		return [][]string{
311			{"root"},
312			{"r2"},
313			{"iso"},
314			{"solo"},
315			{"a", "root"},
316			{"b", "root"},
317			{"z", "a"},
318			{"c", "b"},
319			{"q", "a"},
320			{"m", "c", "z"}, // c listed before z on purpose: c < z at the merge
321			{"long", "z"},
322			{"merge2", "m", "q"},
323			{"d1", "r2"},
324			{"d2", "d1"},
325			{"tip", "merge2", "long"},
326			{"leaf", "tip"},
327		}
328	}
329	
330	// Whole-graph regression: both queries for every registered node agree with
331	// each other and with an independent shortest-path oracle, across direct and
332	// multi-level relations, branch merges and disconnected components.
333	func TestImpactsUpstreamsCorrespondenceAcrossLayeredGraph(t *testing.T) {
334		graph := buildRegisteredGraph(t, layeredCorrespondenceRegistrations())
335		assertConsistent(t, graph)
336		names := sortedGraphNames(graph)
337		oracle := newLineageTestOracle(t, graph)
338		before := snapshot(graph)
339	
340		for _, n := range names {
341			impacts := mustImpacts(t, graph, n)
342			assertImpactListShape(t, graph, n, impacts)
343			if want := expectedImpacts(names, oracle, n); !reflect.DeepEqual(impacts, want) {
344				t.Fatalf("Impacts(%s) = %v, want %v", n, impacts, want)
345			}
346	
347			upstreams := mustUpstreams(t, graph, n)
348			assertUpstreamListShape(t, graph, n, upstreams)
349			if want := expectedUpstreams(names, oracle, n); !reflect.DeepEqual(upstreams, want) {
350				t.Fatalf("Upstreams(%s) = %v, want %v", n, upstreams, want)
351			}
352		}
353	
354		// Every related pair is witnessed identically from both directions, and no
355		// unrelated pair in either direction.
356		assertDirectionsCorrespond(t, graph, names, oracle)
357	
358		// Explicit anchors at the tricky merges.
359	
360		// m is reached over two equal three-edge routes, root->a->z->m and
361		// root->b->c->m. Comparing only m's direct upstreams would wrongly pick the
362		// c route (c < z); the full-path rule first differs at hop 1 where a < b, so
363		// both directions explain m through a and z.
364		impacts := mustImpacts(t, graph, "root")
365		assertImpactOnce(t, impacts, "m", 3, []string{"root", "a", "z", "m"})
366		upstreams := mustUpstreams(t, graph, "m")
367		assertUpstreamOnce(t, upstreams, "root", 3, []string{"root", "a", "z", "m"})
368	
369		// merge2 takes m (depth 3) and q (depth 2): the q route is one edge shorter
370		// and wins from both sides regardless of list order.
371		assertImpactOnce(t, impacts, "merge2", 3, []string{"root", "a", "q", "merge2"})
372		assertUpstreamOnce(t, mustUpstreams(t, graph, "merge2"), "root", 3,
373			[]string{"root", "a", "q", "merge2"})
374	
375		// tip merges merge2 and long, both at depth 3. Its two four-edge routes are
376		// root->a->q->merge2->tip and root->a->z->long->tip; they first differ at
377		// hop 2 where q < z, so the merge2 route explains tip and continues into leaf.
378		assertImpactOnce(t, impacts, "tip", 4, []string{"root", "a", "q", "merge2", "tip"})
379		assertImpactOnce(t, impacts, "leaf", 5, []string{"root", "a", "q", "merge2", "tip", "leaf"})
380		tipUpstreams := mustUpstreams(t, graph, "tip")
381		assertUpstreamOnce(t, tipUpstreams, "root", 4, []string{"root", "a", "q", "merge2", "tip"})
382		assertUpstreamOnce(t, mustUpstreams(t, graph, "leaf"), "root", 5,
383			[]string{"root", "a", "q", "merge2", "tip", "leaf"})
384	
385		// Branch intermediates keep their own, distinct explanations instead of
386		// borrowing the merge node's route.
387		assertImpactOnce(t, impacts, "z", 2, []string{"root", "a", "z"})
388		assertImpactOnce(t, impacts, "c", 2, []string{"root", "b", "c"})
389		assertImpactOnce(t, impacts, "long", 3, []string{"root", "a", "z", "long"})
390		assertUpstreamOnce(t, tipUpstreams, "long", 1, []string{"long", "tip"})
391		assertUpstreamOnce(t, tipUpstreams, "merge2", 1, []string{"merge2", "tip"})
392		assertUpstreamOnce(t, tipUpstreams, "q", 2, []string{"q", "merge2", "tip"})
393		assertUpstreamOnce(t, tipUpstreams, "z", 2, []string{"z", "long", "tip"})
394	
395		// Direct relations at every level are present on both sides with equal rows.
396		assertImpactOnce(t, impacts, "a", 1, []string{"root", "a"})
397		assertImpactOnce(t, impacts, "b", 1, []string{"root", "b"})
398		assertUpstream(t, mustUpstreams(t, graph, "z"), "a", 1, []string{"a", "z"})
399		assertUpstream(t, mustUpstreams(t, graph, "leaf"), "tip", 1, []string{"tip", "leaf"})
400	
401		// The two components and the isolated datasets must never be related in
402		// either direction, while each component stays internally consistent.
403		r2Impacts := mustImpacts(t, graph, "r2")
404		if got, want := impactNames(r2Impacts), []string{"d1", "d2"}; !reflect.DeepEqual(got, want) {
405			t.Fatalf("Impacts(r2) = %v, want only its own component %v", got, want)
406		}
407		assertImpact(t, r2Impacts, "d2", 2, []string{"r2", "d1", "d2"})
408		d2Upstreams := mustUpstreams(t, graph, "d2")
409		if got, want := upstreamNames(d2Upstreams), []string{"d1", "r2"}; !reflect.DeepEqual(got, want) {
410			t.Fatalf("Upstreams(d2) = %v, want only its own component %v", got, want)
411		}
412		assertUpstream(t, d2Upstreams, "r2", 2, []string{"r2", "d1", "d2"})
413		for _, across := range [][2]string{
414			{"root", "r2"}, {"root", "d2"}, {"a", "d1"}, {"m", "d2"},
415			{"r2", "leaf"}, {"iso", "root"}, {"solo", "tip"}, {"d1", "iso"},
416		} {
417			if _, ok := downRecord(mustImpacts(t, graph, across[0]), across[1]); ok {
418				t.Fatalf("%s must not list unrelated %s downstream", across[0], across[1])
419			}
420			if _, ok := upRecord(mustUpstreams(t, graph, across[1]), across[0]); ok {
421				t.Fatalf("%s must not list unrelated %s upstream", across[1], across[0])
422			}
423		}
424	
425		// Registered nodes with no relation in a direction answer with a non-nil
426		// empty list rather than an error or a nil slice.
427		for _, leafName := range []string{"leaf", "d2", "iso", "solo"} {
428			got := mustImpacts(t, graph, leafName)
429			if got == nil || len(got) != 0 {
430				t.Fatalf("Impacts(%s) = %v, want non-nil empty list", leafName, got)
431			}
432		}
433		for _, rootName := range []string{"root", "r2", "iso", "solo"} {
434			got := mustUpstreams(t, graph, rootName)
435			if got == nil || len(got) != 0 {
436				t.Fatalf("Upstreams(%s) = %v, want non-nil empty list", rootName, got)
437			}
438		}
439	
440		// Unregistered names fail in both directions, the error names the dataset
441		// and the result is nil; an empty name is a missing-name error.
442		if got, err := Impacts(graph, "ghost"); err == nil ||
443			!strings.Contains(err.Error(), "ghost") || got != nil {
444			t.Fatalf("Impacts(ghost): want naming error and nil, got %v, %v", got, err)
445		}
446		if got, err := Upstreams(graph, "ghost"); err == nil ||
447			!strings.Contains(err.Error(), "ghost") || got != nil {
448			t.Fatalf("Upstreams(ghost): want naming error and nil, got %v, %v", got, err)
449		}
450		if got, err := Impacts(graph, ""); err == nil ||
451			!strings.Contains(err.Error(), "name is required") || got != nil {
452			t.Fatalf("Impacts(empty): want required-name error and nil, got %v, %v", got, err)
453		}
454		if got, err := Upstreams(graph, ""); err == nil ||
455			!strings.Contains(err.Error(), "name is required") || got != nil {
456			t.Fatalf("Upstreams(empty): want required-name error and nil, got %v, %v", got, err)
457		}
458		if got, err := Impacts(map[string]*Lineage{}, "ghost"); err == nil || got != nil ||
459			!strings.Contains(err.Error(), "ghost") {
460			t.Fatalf("Impacts on empty graph: want naming error and nil, got %v, %v", got, err)
461		}
462		if got, err := Upstreams(nil, "ghost"); err == nil || got != nil ||
463			!strings.Contains(err.Error(), "ghost") {
464			t.Fatalf("Upstreams on nil graph: want naming error and nil, got %v, %v", got, err)
465		}
466	
467		// All queries together leave nodes, relationships and stored list order as
468		// they were before and after.
469		if !reflect.DeepEqual(snapshot(graph), before) {
470			t.Fatalf("queries changed the graph: before=%v after=%v", before, snapshot(graph))
471		}
472		assertConsistent(t, graph)
473	}
