493	// Focused merge regression exercised simultaneously from both directions.
494	// source feeds a and b; a feeds z and d1; b feeds c; report depends on c and z
495	// (c declared first); view derives report; d1 -> d2 and win depends on d2 and b
496	// together; iso stands alone.
497	//
498	//	report: source->a->z->report vs source->b->c->report, equal length. The
499	//	        merge node's own direct-upstream order prefers c (c < z), but the
500	//	        full path first differs at hop 1 (a < b): both queries must choose
501	//	        the a/z route.
502	//	win:    source->b->win is two edges; source->a->d1->d2->win is four edges
503	//	        and is lexicographically smaller at hop 1 (a < b) but longer, so the
504	//	        shorter b route must win from both queries.
505	func TestImpactsUpstreamsMergedBranchesAgreeFromBothDirections(t *testing.T) {
506		build := func() map[string]*Lineage {
507			return buildRegisteredGraph(t, [][]string{
508				{"source"},
509				{"a", "source"},
510				{"b", "source"},
511				{"z", "a"},
512				{"c", "b"},
513				{"report", "c", "z"}, // c ahead of z on purpose
514				{"view", "report"},
515				{"d1", "a"},
516				{"d2", "d1"},
517				{"win", "d2", "b"}, // equal parents ordered against the short-route name
518				{"iso"},
519			})
520		}
521	
522		graph := build()
523		assertConsistent(t, graph)
524		names := sortedGraphNames(graph)
525		oracle := newLineageTestOracle(t, graph)
526		before := snapshot(graph)
527	
528		impacts := mustImpacts(t, graph, "source")
529		wantImpacts := []Impact{
530			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
531			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
532			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
533			{Dataset: "d1", Distance: 2, Path: []string{"source", "a", "d1"}},
534			{Dataset: "win", Distance: 2, Path: []string{"source", "b", "win"}},
535			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
536			{Dataset: "d2", Distance: 3, Path: []string{"source", "a", "d1", "d2"}},
537			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
538			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
539		}
540		if !reflect.DeepEqual(impacts, wantImpacts) {
541			t.Fatalf("Impacts(source) = %v, want %v", impacts, wantImpacts)
542		}
543	
544		upstreams := mustUpstreams(t, graph, "report")
545		wantUpstreams := []Upstream{
546			{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
547			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
548			{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
549			{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
550			{Dataset: "source", Distance: 3, Path: []string{"source", "a", "z", "report"}},
551		}
552		if !reflect.DeepEqual(upstreams, wantUpstreams) {
553			t.Fatalf("Upstreams(report) = %v, want %v", upstreams, wantUpstreams)
554		}
555	
556		// The single shared source->report dependency must read identically from
557		// either query: same distance, same full explanation path.
558		downRow, downOK := downRecord(impacts, "report")
559		upRow, upOK := upRecord(upstreams, "source")
560		if !downOK || !upOK {
561			t.Fatalf("the relation is missing from one side: Impacts=%v Upstreams=%v", downOK, upOK)
562		}
563		if downRow.Distance != upRow.Distance || !reflect.DeepEqual(downRow.Path, upRow.Path) {
564			t.Fatalf("source->report explained differently: downstream %v vs upstream %v", downRow, upRow)
565		}
566		if got, want := downRow.Path, []string{"source", "a", "z", "report"}; !reflect.DeepEqual(got, want) {
567			t.Fatalf("merge path = %v, want %v (full path a<b must beat merge-local c<z)", got, want)
568		}
569	
570		// win's shorter b route beats the lexicographically smaller a route from
571		// both directions, and both sides report the exact same row.
572		assertImpactOnce(t, impacts, "win", 2, []string{"source", "b", "win"})
573		winUpstreams := mustUpstreams(t, graph, "win")
574		wantWinUpstreams := []Upstream{
575			{Dataset: "b", Distance: 1, Path: []string{"b", "win"}},
576			{Dataset: "d2", Distance: 1, Path: []string{"d2", "win"}},
577			{Dataset: "d1", Distance: 2, Path: []string{"d1", "d2", "win"}},
578			{Dataset: "source", Distance: 2, Path: []string{"source", "b", "win"}},
579			{Dataset: "a", Distance: 3, Path: []string{"a", "d1", "d2", "win"}},
580		}
581		if !reflect.DeepEqual(winUpstreams, wantWinUpstreams) {
582			t.Fatalf("Upstreams(win) = %v, want %v", winUpstreams, wantWinUpstreams)
583		}
584		winDown, _ := downRecord(impacts, "win")
585		winUp, _ := upRecord(winUpstreams, "source")
586		if winDown.Distance != 2 || winUp.Distance != 2 ||
587			!reflect.DeepEqual(winDown.Path, []string{"source", "b", "win"}) ||
588			!reflect.DeepEqual(winUp.Path, []string{"source", "b", "win"}) {
589			t.Fatalf("win's longer a-first route must not replace the shorter b route: down=%v up=%v",
590				winDown, winUp)
591		}
592	
593		// Branch intermediates keep their own correct rows on both sides despite
594		// sharing source with each other and report as their merge point: none is
595		// missing, duplicated, or explained through another pair's route.
596		for _, want := range []Impact{
597			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
598			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
599			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
600			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
601			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
602		} {
603			assertImpactOnce(t, impacts, want.Dataset, want.Distance, want.Path)
604		}
605		for _, want := range []Upstream{
606			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
607			{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
608			{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
609			{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
610		} {
611			assertUpstreamOnce(t, upstreams, want.Dataset, want.Distance, want.Path)
612		}
613		// view inherits report's merge explanation; source reaches it only through
614		// report, and the row matches the downstream side exactly.
615		assertUpstreamOnce(t, mustUpstreams(t, graph, "view"), "source", 4,
616			[]string{"source", "a", "z", "report", "view"})
617	
618		// The isolated dataset is related to nothing in either direction.
619		if slices.Contains(impactNames(impacts), "iso") {
620			t.Fatalf("iso leaked into Impacts(source): %v", impactNames(impacts))
621		}
622		if slices.Contains(upstreamNames(upstreams), "iso") {
623			t.Fatalf("iso leaked into Upstreams(report): %v", upstreamNames(upstreams))
624		}
625		isoDown := mustImpacts(t, graph, "iso")
626		isoUp := mustUpstreams(t, graph, "iso")
627		if isoDown == nil || len(isoDown) != 0 || isoUp == nil || len(isoUp) != 0 {
628			t.Fatalf("iso queries must be non-nil empty, got down=%v up=%v", isoDown, isoUp)
629		}
630	
631		// Full pairwise correspondence guard for this graph too.
632		assertDirectionsCorrespond(t, graph, names, oracle)
633		if !reflect.DeepEqual(snapshot(graph), before) {
634			t.Fatalf("queries changed the graph: before=%v after=%v", before, snapshot(graph))
635		}
636	
637		// Adding the direct source->report edge makes edge count win outright: the
638		// three-edge a/z route must disappear from both sides even though it is
639		// lexicographically smaller, and the new edge's position in report's
640		// declared list must not change anything.
641		for _, parents := range [][]string{
642			{"source", "c", "z"},
643			{"z", "c", "source"},
644			{"c", "source", "z"},
645		} {
646			mustRegister(t, graph, "report", parents...)
647			assertConsistent(t, graph)
648	
649			impacts = mustImpacts(t, graph, "source")
650			wantImpacts = []Impact{
651				{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
652				{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
653				{Dataset: "report", Distance: 1, Path: []string{"source", "report"}},
654				{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
655				{Dataset: "d1", Distance: 2, Path: []string{"source", "a", "d1"}},
656				{Dataset: "view", Distance: 2, Path: []string{"source", "report", "view"}},
657				{Dataset: "win", Distance: 2, Path: []string{"source", "b", "win"}},
658				{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
659				{Dataset: "d2", Distance: 3, Path: []string{"source", "a", "d1", "d2"}},
660			}
661			if !reflect.DeepEqual(impacts, wantImpacts) {
662				t.Fatalf("parents %v: Impacts(source) = %v, want %v", parents, impacts, wantImpacts)
663			}
664			upstreams = mustUpstreams(t, graph, "report")
665			wantUpstreams = []Upstream{
666				{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
667				{Dataset: "source", Distance: 1, Path: []string{"source", "report"}},
668				{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
669				{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
670				{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
671			}
672			if !reflect.DeepEqual(upstreams, wantUpstreams) {
673				t.Fatalf("parents %v: Upstreams(report) = %v, want %v", parents, upstreams, wantUpstreams)
674			}
675			assertImpactOnce(t, impacts, "report", 1, []string{"source", "report"})
676			assertImpactOnce(t, impacts, "view", 2, []string{"source", "report", "view"})
677			assertUpstreamOnce(t, upstreams, "source", 1, []string{"source", "report"})
678	
679			// Same dependency, identical row from both directions; the unrelated win
680			// merge and its own explanation are untouched.
681			downRow, _ = downRecord(impacts, "report")
682			upRow, _ = upRecord(upstreams, "source")
683			if downRow.Distance != upRow.Distance || !reflect.DeepEqual(downRow.Path, upRow.Path) {
684				t.Fatalf("parents %v: source->report rows diverge: %v vs %v", parents, downRow, upRow)
685			}
686			assertImpactOnce(t, impacts, "win", 2, []string{"source", "b", "win"})
687			assertDirectionsCorrespond(t, graph, names, newLineageTestOracle(t, graph))
688		}
689	}
