704	// The same final lineage built through different legal registration orders and
705	// with differently ordered direct-upstream lists must yield identical
706	// relations, distances and explanation paths in both directions, for every
707	// registered dataset.
708	func TestImpactsUpstreamsIndependentOfRegistrationOrder(t *testing.T) {
709		sequences := [][][]string{
710			// Baseline: one component top-down, the other early, merge parents in
711			// non-name order.
712			layeredCorrespondenceRegistrations(),
713			// Second component first, branches reversed, every merge's parent list
714			// flipped, roots iso/solo registered last.
715			{
716				{"r2"},
717				{"d1", "r2"},
718				{"d2", "d1"},
719				{"root"},
720				{"b", "root"},
721				{"c", "b"},
722				{"a", "root"},
723				{"z", "a"},
724				{"q", "a"},
725				{"long", "z"},
726				{"m", "z", "c"},
727				{"merge2", "q", "m"},
728				{"tip", "long", "merge2"},
729				{"leaf", "tip"},
730				{"iso"},
731				{"solo"},
732			},
733			// Roots first, middle layer interleaved across components, parent lists
734			// mixed yet differently again.
735			{
736				{"iso"},
737				{"root"},
738				{"r2"},
739				{"solo"},
740				{"a", "root"},
741				{"z", "a"},
742				{"b", "root"},
743				{"c", "b"},
744				{"d1", "r2"},
745				{"long", "z"},
746				{"m", "z", "c"},
747				{"q", "a"},
748				{"merge2", "m", "q"},
749				{"d2", "d1"},
750				{"tip", "merge2", "long"},
751				{"leaf", "tip"},
752			},
753		}
754	
755		graphs := make([]map[string]*Lineage, len(sequences))
756		for i, seq := range sequences {
757			graphs[i] = buildRegisteredGraph(t, seq)
758			assertConsistent(t, graphs[i])
759		}
760	
761		base := graphs[0]
762		baseNames := sortedGraphNames(base)
763		baseEdges := parentEdgeSet(base)
764		for gi := 1; gi < len(graphs); gi++ {
765			g := graphs[gi]
766			if got := parentEdgeSet(g); !reflect.DeepEqual(got, baseEdges) {
767				t.Fatalf("build %d relationships differ: got %v want %v", gi, got, baseEdges)
768			}
769			if names := sortedGraphNames(g); !reflect.DeepEqual(names, baseNames) {
770				t.Fatalf("build %d datasets differ: got %v want %v", gi, names, baseNames)
771			}
772		}
773	
774		// Identical relationships imply identical complete query answers, node by
775		// node, in both directions — ordering included.
776		for _, name := range baseNames {
777			wantDown := mustImpacts(t, base, name)
778			wantUp := mustUpstreams(t, base, name)
779			for gi := 1; gi < len(graphs); gi++ {
780				if got := mustImpacts(t, graphs[gi], name); !reflect.DeepEqual(got, wantDown) {
781					t.Fatalf("build %d Impacts(%s) = %v, want %v", gi, name, got, wantDown)
782				}
783				if got := mustUpstreams(t, graphs[gi], name); !reflect.DeepEqual(got, wantUp) {
784					t.Fatalf("build %d Upstreams(%s) = %v, want %v", gi, name, got, wantUp)
785				}
786			}
787		}
788	
789		// Every build also passes the pairwise two-direction correspondence guard.
790		for gi, g := range graphs {
791			assertDirectionsCorrespond(t, g, sortedGraphNames(g), newLineageTestOracle(t, g))
792			if !slices.Equal(sortedGraphNames(g), baseNames) {
793				t.Fatalf("build %d dataset set changed after queries", gi)
794			}
795		}
796	}
